/**
 * generated by stackra gen from src/config/seo.config.ts (sitemaps), the marketing routes
 * (landing, pricing, contact) and the sitemap sources of the consumed manifests (experience
 * pages.sitemap.get, commerce catalogue.product.list_storefront@1) — do not edit
 * Purpose: the sitemap sources: the marketing routes, the tenant's builder pages and the storefront
 *          products. Each `list` answers one cursor page (or everything, when the query has no
 *          cursor); `@stackra/seo/sitemap` walks the cursors into numbered files and
 *          `route-modules/sitemap.ts` writes the XML.
 * Boundary: data plus the listers bound to the consumed queries; links are built from
 *           `#stackra/routes` keys, so no route module is imported.
 * Runtime: worker
 */
import type { SitemapSource } from "@stackra/seo/sitemap";
import { Changefreq } from "@stackra/seo";
import type { PublicClients } from "#stackra/clients.server";
import { ListStorefrontProductsQuery } from "#stackra/clients/commerce";
import { GetPagesSitemapQuery } from "#stackra/clients/experience";
import { Routes } from "#stackra/routes";

/** Build timestamp the generated Vite config defines; `lastmod` of the marketing routes. */
declare const __BUILD_TIME__: string;

/** One source per name; the index lists `/sitemaps/<name>-<page>.xml` for each. */
export const sitemapSources: Record<string, SitemapSource<PublicClients>> = {
  marketing: {
    changefreq: Changefreq.Weekly,
    list: async (_clients, _site, href) => ({
      items: [Routes.landing, Routes.pricing, Routes.contact].map((route) => ({
        path: href(route),
        updatedAt: __BUILD_TIME__,
      })),
    }),
  },
  pages: {
    changefreq: Changefreq.Weekly,
    // one answer with every published path; the helper splits it into files of `pageSize`
    list: async (clients, site) => ({
      items: (await clients.query(GetPagesSitemapQuery, { siteId: site.siteId }))
        .entries,
    }),
  },
  products: {
    changefreq: Changefreq.Daily,
    maxLimit: 100, // catalogue.product.list_storefront@1's own `limit` ceiling
    list: async (clients, _site, href, { cursor, limit }) => {
      const page = await clients.query(ListStorefrontProductsQuery, {
        ...(cursor ? { cursor } : {}),
        limit,
      });
      return {
        items: page.items.map((product) => ({
          path: href(Routes.product, { slug: product.slug }),
          ...(product.image ? { image: product.image.url } : {}),
        })),
        ...(page.nextCursor ? { nextCursor: page.nextCursor } : {}),
      };
    },
  },
};
